/** Msg defines the custody Msg service. */
export interface Msg {
  /** RegisterAsset lists an asset this chain will issue claims on. Governance. */
  RegisterAsset(request: MsgRegisterAsset): Promise<MsgRegisterAssetResponse>;
  /** SetAttestor appoints or removes an attestor. Governance. */
  SetAttestor(request: MsgSetAttestor): Promise<MsgSetAttestorResponse>;
  /** AttestDeposit records that a deposit was seen on the source chain. */
  AttestDeposit(request: MsgAttestDeposit): Promise<MsgAttestDepositResponse>;
  /** ReportReserve states what the custodian holds against an asset. */
  ReportReserve(request: MsgReportReserve): Promise<MsgReportReserveResponse>;
  /** RequestRedemption burns a claim and queues the payout. */
  RequestRedemption(request: MsgRequestRedemption): Promise<MsgRequestRedemptionResponse>;
  /** SettleRedemption records that the payout was made. */
  SettleRedemption(request: MsgSettleRedemption): Promise<MsgSettleRedemptionResponse>;
  /** UpdateParams sets the module parameters. Governance. */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
}

